    static double dMult(Point a, Point b) { return a.x * b.x + a.y * b.y; }
    static double xMult(Point a, Point b) { return a.x * b.y - a.y * b.x; }
    static double vecMod(Point a) { return Math.sqrt(dMult(a, a)); }
    static double vecMod2(Point a) { return dMult(a, a); }
    static double corner2V(Point a, Point b) {
        double modA = vecMod(a);
        double modB = vecMod(b);
        if (modA < EPS || modB < EPS) return 0;
        double cos = dMult(a, b) / modA / modB;
        if (cos > 1) cos = 1;
        if (cos < -1) cos = -1;
        return Math.abs(Math.acos(cos));
    }
    static Point vecUnit(Point a) { return a.div(vecMod(a)); }
    static Point vRotate(Point v, double alph) {
        double sa = Math.sin(alph), ca = Math.cos(alph);
        return new Point(v.x * ca - v.y * sa, v.x * sa + v.y * ca);
    }
    static Point pRotate(Point p, Point o, double alph) {
        return o.add(vRotate(ptoV(o, p), alph));
    }
    static Point getVV(Point v) { return vRotate(v, PI / 2); }

    static Point shadowPOnLine(Point p, Point a, Point b) {
        Point ab = ptoV(a, b);
        Point ap = ptoV(a, p);
        double abMod = vecMod(ab);
        if (abMod < EPS) return new Point(a); // degenerate
        Point alph = vecUnit(ab).mul(dMult(ab, ap) / abMod);
        return a.add(alph);
