        return vecMod(ptoV(s, ttp1.get(0))) + vecMod(ptoV(e, ttp2.get(0))) + alph * r < vs * t;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        // C++: while(cin >> p >> vp >> s >> vs >> r)
        // Input order: p.x p.y vp s.x s.y vs r
        while (scanner.hasNextDouble()) {
